Just for fun, I made a tiny script that sorts your data.

The heart of it is just this little function:

function sparseSort(range, sortOnCol, ascending) {
    let data = range.getValues();
    let orderedData = data.filter( r => r.some( x => !empty(x) ) )
                          .sort( (a,b) => {
                               if( a[sortOnCol] < b[sortOnCol] ) return ascending ? -1 : 1;
                               if( a[sortOnCol] > b[sortOnCol] ) return ascending ? 1 : -1;
                               return 0;
                           });
    let j = 0;
    for( let i = 0; i < data.length; i++ ) {
        if( data[i].some( x => !empty(x) ) )
            data[i] = orderedData[j++];
    }

    range.setValues(data);
}

function empty(x) {
    return x === undefined || x === null || x === '';
}

And then I got some help from the almost intelligence to throw up a sidebar around it :)

